  return (
    <section
      id="membership"
      data-tone="light"
      className="relative bg-[#FAF9F6] py-14 sm:py-20 border-t border-neutral-200/80 overflow-hidden"
    >
      <div className="mx-auto w-full max-w-[1360px] px-4 sm:px-6 lg:px-10 flex flex-col">
        {/* Header Block */}
